// Validate input and generate story ID
const formData = $input.first().json;

// Validate number of scenes (1-12)
let numScenes = parseInt(formData['Number of Scenes']) || 4;
if (numScenes < 1) numScenes = 1;
if (numScenes > 12) numScenes = 12;

// Generate unique story ID
const storyId = `story_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

return {
  json: {
    ...formData,
    numScenes: numScenes,
    storyId: storyId
  }
};

// Prepare story data for image generation
const response = $input.first().json;
const formData = $('Validate Input1').first().json;
const imageStyle = formData['Image Style'];

const story = JSON.parse(response.choices[0].message.content);

function sanitize(text) {
  if (!text) return '';
  return text
    .replace(/\\/g, '\\\\')
    .replace(/"/g, "'")
    .replace(/\n/g, ' ')
    .replace(/\r/g, '')
    .replace(/\t/g, ' ')
    .replace(/[\x00-\x1F\x7F]/g, '')
    .trim();
}

const preparedScenes = story.scenes.map((scene, index) => {
  const dallePrompt = `${imageStyle}, children's book illustration: ${sanitize(scene.imagePrompt)}. High quality, vibrant colors, no text in image.`;

  return {
    ...scene,
    sceneIndex: index,
    dallePrompt: dallePrompt.substring(0, 4000),
    imageUrl: null
  };
});

return {
  json: {
    story: { ...story, scenes: preparedScenes },
    formData: formData,
    storyId: formData.storyId,
    totalScenes: preparedScenes.length,
    createdAt: new Date().toISOString()
  }
};

return items.map(item => {
  const texto = item.json.output || "";

  // If already within the limit, return as is
  if (texto.length <= 4000) {
    return { json: { output: texto } };
  }

  const limite = 4000;
  const subTexto = texto.slice(0, limite);

  // Find the last punctuation mark before the limit
  const regexPontuacao = /[.!?]/g;
  let ultimoIndice = -1;
  let match;

  while ((match = regexPontuacao.exec(subTexto)) !== null) {
    ultimoIndice = match.index;
  }

  // Cut at the last punctuation if found, otherwise at the limit
  const textoCortado =
    ultimoIndice !== -1
      ? subTexto.slice(0, ultimoIndice + 1).trim()
      : subTexto.trim();

  return { json: { output: textoCortado } };
});

// In JavaScript2 nodes, the current item is usually available as $json
const originalText = $json.output || $json.text || '';

// Format the text
const formattedText = originalText
  .replace(/[\r\n]+/g, ' ')  // Replace newlines with a single space
  .replace(/\s+/g, ' ')      // Collapse multiple spaces
  .trim();                    // Remove leading/trailing spaces

// Return the updated item
return {
  json: {
    ...$json,
    text: formattedText
  }
};

// previousNodeData is the variable that holds the output from the previous node
// Example: it could be fetched dynamically every time
// Make sure previousNodeData is an array of objects
const previousNodeData = $input.all(); // or the variable storing the previous node output

if (!Array.isArray(previousNodeData) || previousNodeData.length === 0) {
  // Handle empty previous node output
  return [];
}

// Pick a random index
const randomIndex = Math.floor(Math.random() * previousNodeData.length);

// Get the random item
const randomItem = previousNodeData[randomIndex];

// Wrap it in an array so downstream nodes receive an array
return [randomItem];

// Input: JSON with story.scenes array
const story = items[0].json.story; // your story object

// Merge all scene texts
const mergedText = story.scenes
  .map(scene => scene.textEnglish || scene.text || '')
  .filter(text => text.trim() !== '')
  .join('\n\n'); // separate scenes by double newline

// Return merged text
return [{
  json: {
    mergedText
  }
}];

// Input: mergedText from previous node
const mergedText = (items[0]?.json?.mergedText || '').trim();

// Return empty if no text
if (!mergedText) {
  return [{
    json: { message: 'No text to generate SRT' }
  }];
}

// Settings
const minDuration = 1; // minimum seconds per line
const maxDuration = 3; // maximum seconds per line
const wordsPerSecond = 2; // approximate reading speed (words/sec)

// Split mergedText into words
const words = mergedText.split(/\s+/);

// Function to split words into subtitle lines
let lines = [];
let lineWords = [];
let wordCounter = 0;

for (let i = 0; i < words.length; i++) {
  lineWords.push(words[i]);
  wordCounter++;

  // Estimate duration for current line
  const duration = Math.max(minDuration, Math.min(maxDuration, lineWords.length / wordsPerSecond));

  // Finalize line if duration >= maxDuration OR last word
  if (duration >= maxDuration || i === words.length - 1) {
    lines.push({
      text: lineWords.join(' '),
      duration: duration
    });
    lineWords = [];
  }
}

// Function to format time for SRT
function formatTime(sec) {
  const h = String(Math.floor(sec / 3600)).padStart(2, '0');
  const m = String(Math.floor((sec % 3600) / 60)).padStart(2, '0');
  const s = String(Math.floor(sec % 60)).padStart(2, '0');
  const ms = String(Math.floor((sec % 1) * 1000)).padStart(3, '0');
  return `${h}:${m}:${s},${ms}`;
}

// Build SRT content
let srtContent = '';
let currentTime = 0;

lines.forEach((line, index) => {
  const start = formatTime(currentTime);
  const end = formatTime(currentTime + line.duration);
  srtContent += `${index + 1}\n${start} --> ${end}\n${line.text}\n\n`;
  currentTime += line.duration;
});

// Return SRT as binary for Write Binary File node
return [{
  json: {},
  binary: {
    srt: {
      data: Buffer.from(srtContent, 'utf-8'),
      mimeType: 'application/x-subrip',
      fileName: 'story_subtitles.srt'
    }
  }
}];

// Get all incoming items
const items = $input.all();

// Check that there is at least 2 items to merge
if (items.length < 2) {
  throw new Error(`Expected at least 2 items, got ${items.length}`);
}

// Prepare a new output item with all binary data
const mergedBinary = {};

// Loop through each item and add its binary properties to the mergedBinary
items.forEach((item, index) => {
  // Get the first binary property in this item
  const binaryKeys = Object.keys(item.binary);
  if (binaryKeys.length === 0) {
    throw new Error(`Item ${index} has no binary data`);
  }

  // Use a key like data0, data1, data2, ...
  mergedBinary[`data${index}`] = item.binary[binaryKeys[0]];
});

// Return the merged binary data
return [
  {
    json: {},
    binary: mergedBinary
  }
];

