={
  "model": "gpt-4o",
  "messages": [
    {
      "role": "system",
      "content": "You are a master storyteller creating illustrated stories. Generate engaging narratives with vivid, DALL-E-friendly image prompts. Keep prompts concise but descriptive."
    },
    {
      "role": "user",
      "content": "Create an illustrated story:\n\nTOPIC: {{ $json['Story Topic'] }}\n\nSPECS:\n- Language: {{ $json.Language }}\n- Scenes: {{ $json.numScenes }}\n- Audience: {{ $json['Target Audience'] }}\n- Mood: {{ $json['Story Mood'] }}\n- Art style: {{ $json['Image Style'] }}\n\nRULES:\n1. Exactly {{ $json.numScenes }} scenes\n2. Write story text in {{ $json.Language }}\n3. Image prompts in English, include art style\n4. Age-appropriate content\n5. Clear beginning, middle, end"
    }
  ],
  "response_format": {
    "type": "json_schema",
    "json_schema": {
      "name": "illustrated_story",
      "strict": true,
      "schema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "title": { "type": "string" },
          "titleEnglish": { "type": "string" },
          "summary": { "type": "string" },
          "summaryEnglish": { "type": "string" },
          "language": { "type": "string" },
          "targetAudience": { "type": "string" },
          "mood": { "type": "string" },
          "moral": { "type": "string" },
          "scenes": {
            "type": "array",
            "items": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "sceneNumber": { "type": "number" },
                "title": { "type": "string" },
                "text": { "type": "string" },
                "textEnglish": { "type": "string" },
                "imagePrompt": { "type": "string" }
              },
              "required": ["sceneNumber", "title", "text", "textEnglish", "imagePrompt"]
            }
          },
          "characters": {
            "type": "array",
            "items": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "name": { "type": "string" },
                "description": { "type": "string" },
                "role": { "type": "string" }
              },
              "required": ["name", "description", "role"]
            }
          }
        },
        "required": ["title", "titleEnglish", "summary", "summaryEnglish", "language", "targetAudience", "mood", "moral", "scenes", "characters"]
      }
    }
  }
}

